		SailResultValueExposure exposure = (SailResultValueExposure) sail;
		IllegalStateException expected = new IllegalStateException("cannot acquire exposure ownership");
		IllegalStateException closeFailure = new IllegalStateException("source cleanup failed");
		CloseableIteration<Statement> source = mock(CloseableIteration.class);
		when(exposure.exposeIteration(source, SailResultValueExtractor.STATEMENTS)).thenThrow(expected);
		doThrow(closeFailure).when(source).close();
